-- 037_import_hash_and_concurrency.sql
create extension if not exists pgcrypto;
create or replace function intake.payload_hash(p_payload jsonb) returns text language plpgsql immutable strict as $$ declare s text; h bigint:=2166136261; c integer; i integer; begin select coalesce(string_agg(format('%s:%s',e.key,lower(trim(both from coalesce(e.value #>> '{}','')))),'|' order by e.key),'') into s from jsonb_each(p_payload) e; for i in 1..length(s) loop c:=ascii(substr(s,i,1)); h:=(h # c); h:=(h*16777619)%4294967296; end loop; return lpad(to_hex(h),8,'0'); end; $$;
revoke all on function intake.payload_hash(jsonb) from public,anon,authenticated; grant execute on function intake.payload_hash(jsonb) to service_role;
create or replace function intake.canonical_row_hash(p_table text,p_id bigint) returns text language plpgsql security definer stable set search_path=intake,public,pg_catalog as $$ declare payload jsonb; begin if p_table not in ('client','programme','quotation','purchase_order','invoice','payment') then raise exception 'Unsupported table'; end if; execute format('select to_jsonb(t) from public.%I t where t.id=$1',p_table) using p_id into payload; if payload is null then return null; end if; return intake.payload_hash(payload); end; $$;
revoke all on function intake.canonical_row_hash(text,bigint) from public,anon,authenticated; grant execute on function intake.canonical_row_hash(text,bigint) to service_role;
